{
  "name": "TaxRegion BR",
  "description": "Plataforma de Inteligência Tributária Estadual baseada em IA para análise de incentivos fiscais e regimes especiais no Brasil."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface State {
  uf: string;
  name: string;
}

export enum TaxTopicId {
  ICMS = 'icms',
  REGIMES = 'regimes',
  ZONES = 'zones'
}

export interface TaxTopic {
  id: TaxTopicId;
  title: string;
  description: string;
  icon: 'chart' | 'document' | 'location';
}

export interface AnalysisResult {
  markdown: string;
  timestamp: string;
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
}

import { GoogleGenAI } from "@google/genai";
import { State, TaxTopic } from '../types';

// Use gemini-3-pro-preview for complex reasoning tasks like tax analysis
const MODEL_NAME = 'gemini-3-pro-preview';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeTaxScenario = async (state: State, topic: TaxTopic): Promise<string> => {
  const prompt = `
    Você é um consultor tributário sênior especializado em legislação brasileira (Tax Intelligence).

    Tarefa: Forneça uma análise estratégica sobre "${topic.title}" especificamente para o estado de ${state.name} (${state.uf}).

    Estruture a resposta em Markdown claro e profissional com os seguintes pontos:
    1. **Resumo Executivo**: Uma visão geral da postura do estado quanto a ${topic.title}.
    2. **Principais Oportunidades**: Liste benefícios, incentivos ou regimes vigentes mais relevantes.
    3. **Legislação Chave**: Cite as leis ou decretos estaduais relevantes (se houver conhecimento específico, caso contrário, indique como buscar).
    4. **Pontos de Atenção**: Riscos ou exigências comuns para adesão.

    Contexto adicional: O usuário busca otimização fiscal. Seja objetivo, mas detalhado o suficiente para gerar valor. Use formatação em tópicos.

    Importante: Adicione um aviso ao final de que a legislação muda frequentemente e a consulta oficial é indispensável.
  `;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: {
        thinkingConfig: { thinkingBudget: 1024 }, // Enable thinking for deeper analysis
      }
    });
    return response.text || "Não foi possível gerar a análise no momento.";
  } catch (error) {
    console.error("Error fetching tax analysis:", error);
    return "Ocorreu um erro ao consultar a inteligência tributária. Por favor, tente novamente.";
  }
};

export const chatWithTaxExpert = async (message: string, history: {role: string, parts: {text: string}[]}[]): Promise<string> => {
  try {
    const chat = ai.chats.create({
      model: MODEL_NAME,
      history: [
        {
          role: 'user',
          parts: [{ text: "Você é o assistente virtual do TaxRegion BR. Você ajuda com dúvidas sobre tributação estadual no Brasil. Seja profissional, conciso e sempre lembre que suas respostas são consultivas e não substituem parecer jurídico. Responda sempre em Português." }]
        },
        {
          role: 'model',
          parts: [{ text: "Entendido. Sou o assistente do TaxRegion BR e estou pronto para auxiliar com inteligência tributária, mantendo o tom profissional e consultivo." }]
        },
        ...history
      ],
    });

    const response = await chat.sendMessage({ message });
    return response.text || "Desculpe, não consegui processar sua pergunta.";
  } catch (error) {
    console.error("Chat error:", error);
    return "Erro de conexão com o assistente inteligente.";
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { IconChat, IconClose, IconArrowRight, IconGemini } from './Icons';
import { ChatMessage } from '../types';
import { chatWithTaxExpert } from '../services/geminiService';

const ChatBot: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSendMessage = async (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!inputValue.trim() || isLoading) return;

    const userMsg: ChatMessage = { role: 'user', text: inputValue };
    setMessages(prev => [...prev, userMsg]);
    setInputValue('');
    setIsLoading(true);

    // Prepare history for API
    const history = messages.map(m => ({
      role: m.role,
      parts: [{ text: m.text }]
    }));

    const responseText = await chatWithTaxExpert(userMsg.text, history);

    setMessages(prev => [...prev, { role: 'model', text: responseText }]);
    setIsLoading(false);
  };

  return (
    <>
      {/* Floating Button */}
      <button
        onClick={() => setIsOpen(!isOpen)}
        className="fixed bottom-6 right-6 z-50 p-4 bg-emerald-600 hover:bg-emerald-500 text-white rounded-full shadow-lg transition-all duration-300 transform hover:scale-105 flex items-center justify-center group"
        aria-label="Abrir Chat"
      >
        {isOpen ? <IconClose className="w-6 h-6" /> : <IconChat className="w-6 h-6" />}
      </button>

      {/* Chat Window */}
      {isOpen && (
        <div className="fixed bottom-24 right-6 w-96 max-w-[calc(100vw-3rem)] h-[500px] bg-slate-900 border border-slate-700 rounded-2xl shadow-2xl flex flex-col z-50 animate-fade-in overflow-hidden">
          {/* Header */}
          <div className="bg-slate-800 p-4 border-b border-slate-700 flex items-center justify-between">
            <div className="flex items-center space-x-2">
              <div className="w-8 h-8 rounded-full bg-emerald-500/10 flex items-center justify-center border border-emerald-500/20">
                <IconGemini className="w-5 h-5 text-emerald-400" />
              </div>
              <div>
                <h3 className="font-semibold text-slate-100 text-sm">Assistente TaxRegion</h3>
                <span className="text-xs text-emerald-400 flex items-center gap-1">
                  <span className="w-1.5 h-1.5 rounded-full bg-emerald-400 animate-pulse"></span>
                  Online
                </span>
              </div>
            </div>
            <button onClick={() => setIsOpen(false)} className="text-slate-400 hover:text-white">
               <IconClose className="w-5 h-5" />
            </button>
          </div>

          {/* Messages Area */}
          <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-900/50">
            {messages.length === 0 && (
              <div className="text-center text-slate-500 mt-10 text-sm">
                <IconChat className="w-12 h-12 mx-auto mb-3 opacity-20" />
                <p>Olá! Sou sua IA tributária.</p>
                <p className="text-xs mt-1">Pergunte sobre ICMS, incentivos ou dúvidas fiscais.</p>
              </div>
            )}

            {messages.map((msg, idx) => (
              <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div 
                  className={`max-w-[85%] p-3 rounded-2xl text-sm leading-relaxed ${
                    msg.role === 'user' 
                      ? 'bg-emerald-600 text-white rounded-br-none' 
                      : 'bg-slate-800 text-slate-200 border border-slate-700 rounded-bl-none'
                  }`}
                >
                  {msg.text}
                </div>
              </div>
            ))}

            {isLoading && (
              <div className="flex justify-start">
                <div className="bg-slate-800 border border-slate-700 p-3 rounded-2xl rounded-bl-none flex items-center space-x-2">
                  <div className="w-2 h-2 bg-slate-500 rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></div>
                  <div className="w-2 h-2 bg-slate-500 rounded-full animate-bounce" style={{ animationDelay: '150ms' }}></div>
                  <div className="w-2 h-2 bg-slate-500 rounded-full animate-bounce" style={{ animationDelay: '300ms' }}></div>
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          {/* Input Area */}
          <form onSubmit={handleSendMessage} className="p-3 bg-slate-800 border-t border-slate-700">
            <div className="relative">
              <input
                type="text"
                value={inputValue}
                onChange={(e) => setInputValue(e.target.value)}
                placeholder="Digite sua dúvida..."
                className="w-full bg-slate-900 border border-slate-700 text-white placeholder-slate-500 rounded-xl py-3 pl-4 pr-12 focus:outline-none focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500 transition-all text-sm"
              />
              <button
                type="submit"
                disabled={!inputValue.trim() || isLoading}
                className="absolute right-2 top-1/2 -translate-y-1/2 p-1.5 bg-emerald-600 hover:bg-emerald-500 text-white rounded-lg disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
              >
                <IconArrowRight className="w-4 h-4" />
              </button>
            </div>
            <p className="text-[10px] text-slate-500 text-center mt-2">
              IA pode cometer erros. Valide com um contador.
            </p>
          </form>
        </div>
      )}
    </>
  );
};

export default ChatBot;

import React, { useState } from 'react';
import { BRAZIL_STATES, TAX_TOPICS } from './constants';
import { State, TaxTopic, AnalysisResult } from './types';
import { analyzeTaxScenario } from './services/geminiService';
import { IconChart, IconDocument, IconLocation, IconGemini, IconArrowRight } from './components/Icons';
import ChatBot from './components/ChatBot';

const App: React.FC = () => {
  const [selectedState, setSelectedState] = useState<State | null>(null);
  const [activeAnalysis, setActiveAnalysis] = useState<{ topic: TaxTopic; result: AnalysisResult | null; loading: boolean } | null>(null);

  const handleStateChange = (event: React.ChangeEvent<HTMLSelectElement>) => {
    const uf = event.target.value;
    const state = BRAZIL_STATES.find((s) => s.uf === uf) || null;
    setSelectedState(state);
    // Reset analysis if state changes
    setActiveAnalysis(null);
  };

  const handleTopicClick = async (topic: TaxTopic) => {
    if (!selectedState) {
      // Focus on selector if no state selected
      const selector = document.getElementById('state-selector');
      if (selector) {
        selector.focus();
        selector.classList.add('ring-2', 'ring-emerald-500', 'ring-offset-2', 'ring-offset-slate-900');
        setTimeout(() => selector.classList.remove('ring-2', 'ring-emerald-500', 'ring-offset-2', 'ring-offset-slate-900'), 1000);
      }
      return;
    }

    setActiveAnalysis({ topic, result: null, loading: true });

    // Simulate loading feel or actual delay for UI smoothing if API is too fast/slow
    const startTime = Date.now();
    const markdown = await analyzeTaxScenario(selectedState, topic);
    const endTime = Date.now();

    // Ensure at least 800ms loading for UX presence
    const elapsed = endTime - startTime;
    if (elapsed < 800) {
      await new Promise(resolve => setTimeout(resolve, 800 - elapsed));
    }

    setActiveAnalysis({
      topic,
      result: {
        markdown,
        timestamp: new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })
      },
      loading: false
    });
  };

  const renderTopicIcon = (iconType: string, className: string) => {
    switch(iconType) {
      case 'chart': return <IconChart className={className} />;
      case 'document': return <IconDocument className={className} />;
      case 'location': return <IconLocation className={className} />;
      default: return <IconChart className={className} />;
    }
  };

  const formatMarkdown = (text: string) => {
    // Simple markdown formatter for the demo (in production, use a library like react-markdown)
    const lines = text.split('\n');
    return lines.map((line, idx) => {
      if (line.startsWith('### ')) return <h3 key={idx} className="text-lg font-semibold text-emerald-400 mt-4 mb-2">{line.replace('### ', '')}</h3>;
      if (line.startsWith('## ')) return <h2 key={idx} className="text-xl font-bold text-slate-100 mt-6 mb-3 pb-1 border-b border-slate-700">{line.replace('## ', '')}</h2>;
      if (line.startsWith('**')) return <strong key={idx} className="block mt-2 text-slate-200">{line.replace(/\*\*/g, '')}</strong>;
      if (line.trim().startsWith('- ')) return <li key={idx} className="ml-4 text-slate-300 list-disc">{line.replace('- ', '')}</li>;
      if (line.trim().startsWith('1. ')) return <li key={idx} className="ml-4 text-slate-300 list-decimal">{line.replace(/[0-9]+\. /, '')}</li>;
      if (line.trim() === '') return <br key={idx} />;
      return <p key={idx} className="text-slate-300 leading-relaxed mb-2">{line.replace(/\*\*/g, '')}</p>;
    });
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#020617] text-slate-50 selection:bg-emerald-500/30">

      {/* Navbar */}
      <nav className="w-full border-b border-slate-800 bg-[#020617]/90 backdrop-blur-sm sticky top-0 z-40">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-20 flex items-center justify-between">
          <div className="flex items-center gap-3">
             <div className="relative">
                <div className="absolute -inset-1 bg-gradient-to-r from-emerald-500 to-blue-500 rounded-full blur opacity-20"></div>
                <div className="relative bg-slate-900 rounded-full p-2 border border-slate-700">
                    <IconChart className="w-6 h-6 text-emerald-400" />
                </div>
             </div>
             <div>
                <h1 className="text-2xl font-bold tracking-tight text-white">
                  Tax<span className="text-emerald-400">Region</span> <span className="text-slate-500 font-light">BR</span>
                </h1>
                <p className="text-[10px] text-slate-400 uppercase tracking-widest leading-none mt-0.5">Inteligência Tributária</p>
             </div>
          </div>

          <div className="hidden md:flex items-center gap-2 px-3 py-1.5 rounded-full bg-slate-900 border border-slate-800">
            <IconGemini className="w-4 h-4 text-emerald-500" />
            <span className="text-xs font-medium text-slate-300">Powered by Gemini</span>
          </div>
        </div>
      </nav>

      {/* Hero Section */}
      <main className="flex-grow flex flex-col items-center w-full max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12 md:py-20">

        <div className="text-center max-w-3xl mx-auto mb-16 animate-fade-in">
          <div className="inline-flex items-center gap-2 px-4 py-2 rounded-full bg-slate-900/50 border border-slate-700 mb-8">
             <span className="relative flex h-2 w-2">
               <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75"></span>
               <span className="relative inline-flex rounded-full h-2 w-2 bg-emerald-500"></span>
             </span>
             <span className="text-xs font-medium text-emerald-400 tracking-wide">DADOS EM TEMPO REAL VIA IA</span>
          </div>

          <h2 className="text-4xl md:text-5xl lg:text-6xl font-bold text-white tracking-tight mb-6 leading-tight">
            Navegue pela complexidade dos <span className="text-transparent bg-clip-text bg-gradient-to-r from-emerald-400 to-cyan-400">incentivos fiscais</span>
          </h2>
          <p className="text-lg text-slate-400 leading-relaxed mb-10 max-w-2xl mx-auto">
            Identifique oportunidades de economia tributária, regimes especiais e benefícios regionais com análises contextuais geradas por Inteligência Artificial.
          </p>

          {/* Stats */}
          <div className="grid grid-cols-3 gap-8 border-t border-slate-800 pt-8 max-w-lg mx-auto">
            <div className="flex flex-col items-center">
              <span className="text-2xl font-bold text-white">27</span>
              <span className="text-xs text-slate-500 uppercase tracking-wider mt-1">Estados</span>
            </div>
            <div className="flex flex-col items-center">
              <span className="text-2xl font-bold text-white">500+</span>
              <span className="text-xs text-slate-500 uppercase tracking-wider mt-1">Benefícios</span>
            </div>
            <div className="flex flex-col items-center">
              <span className="text-2xl font-bold text-white">24/7</span>
              <span className="text-xs text-slate-500 uppercase tracking-wider mt-1">Atualizado</span>
            </div>
          </div>
        </div>

        {/* State Selection */}
        <div className="w-full max-w-md mx-auto mb-20 relative z-10">
          <label htmlFor="state-selector" className="block text-sm font-medium text-slate-400 mb-2 text-center uppercase tracking-widest">
            Selecione o Estado (UF)
          </label>
          <div className="relative">
            <select
              id="state-selector"
              value={selectedState?.uf || ''}
              onChange={handleStateChange}
              className="appearance-none block w-full bg-slate-900 border border-slate-700 text-white py-4 px-6 rounded-xl leading-tight focus:outline-none focus:ring-2 focus:ring-emerald-500 focus:border-transparent text-lg shadow-2xl transition-all cursor-pointer hover:border-slate-600"
            >
              <option value="" disabled>Escolha a UF</option>
              {BRAZIL_STATES.map((state) => (
                <option key={state.uf} value={state.uf}>
                  {state.name} ({state.uf})
                </option>
              ))}
            </select>
            <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-4 text-slate-400">
              <svg className="fill-current h-4 w-4" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20">
                <path d="M9.293 12.95l.707.707L15.657 8l-1.414-1.414L10 10.828 5.757 6.586 4.343 8z" />
              </svg>
            </div>
          </div>
        </div>

        {/* Action Pillars Section */}
        <div className="w-full mb-16">
          <h3 className="text-2xl font-bold text-center text-white mb-2">O que você deseja consultar?</h3>
          <p className="text-center text-slate-400 mb-10">Selecione uma categoria para iniciar sua análise tributária personalizada</p>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            {TAX_TOPICS.map((topic) => (
              <button
                key={topic.id}
                onClick={() => handleTopicClick(topic)}
                className={`group relative flex flex-col items-start p-8 rounded-2xl border transition-all duration-300 text-left hover:shadow-2xl hover:-translate-y-1 ${
                  activeAnalysis?.topic.id === topic.id 
                    ? 'bg-slate-800/80 border-emerald-500/50 shadow-emerald-900/20' 
                    : 'bg-slate-900/50 border-slate-800 hover:border-emerald-500/30 hover:bg-slate-800'
                }`}
              >
                <div className={`p-3 rounded-lg mb-6 transition-colors ${
                   activeAnalysis?.topic.id === topic.id ? 'bg-emerald-500/20 text-emerald-400' : 'bg-slate-800 text-slate-400 group-hover:text-emerald-400 group-hover:bg-slate-900'
                }`}>
                  {renderTopicIcon(topic.icon, "w-8 h-8")}
                </div>
                <h4 className="text-xl font-bold text-white mb-3 group-hover:text-emerald-400 transition-colors">{topic.title}</h4>
                <p className="text-slate-400 text-sm leading-relaxed mb-8 flex-grow">
                  {topic.description}
                </p>
                <div className="flex items-center text-sm font-semibold text-emerald-500 mt-auto opacity-0 group-hover:opacity-100 transition-opacity -translate-x-2 group-hover:translate-x-0 duration-300">
                   {selectedState ? `Consultar ${selectedState.uf}` : 'Selecione um estado'} 
                   <IconArrowRight className="w-4 h-4 ml-2" />
                </div>
              </button>
            ))}
          </div>
        </div>

        {/* Results Section */}
        {activeAnalysis && (
          <div className="w-full max-w-4xl mx-auto animate-fade-in mb-16">
            <div className="bg-slate-900 rounded-2xl border border-slate-700 overflow-hidden shadow-2xl relative">

              {/* Header of Card */}
              <div className="px-8 py-6 border-b border-slate-800 bg-slate-900/50 flex items-center justify-between">
                <div className="flex items-center gap-4">
                  <div className="p-2 bg-emerald-500/10 rounded-lg">
                    {renderTopicIcon(activeAnalysis.topic.icon, "w-6 h-6 text-emerald-500")}
                  </div>
                  <div>
                    <h3 className="text-lg font-bold text-white">{activeAnalysis.topic.title}</h3>
                    <p className="text-sm text-slate-400">Análise para <span className="text-emerald-400 font-semibold">{selectedState?.name}</span></p>
                  </div>
                </div>
                <div className="flex items-center gap-2 px-3 py-1 rounded-full bg-slate-800 border border-slate-700 text-xs text-slate-400">
                  <IconGemini className={`w-3 h-3 ${activeAnalysis.loading ? 'animate-pulse text-emerald-400' : 'text-slate-500'}`} />
                  {activeAnalysis.loading ? 'Processando...' : 'Gerado por Gemini'}
                </div>
              </div>

              {/* Content */}
              <div className="p-8 min-h-[300px]">
                {activeAnalysis.loading ? (
                  <div className="flex flex-col items-center justify-center h-full py-12 space-y-4">
                    <div className="relative w-16 h-16">
                       <div className="absolute inset-0 border-4 border-slate-800 rounded-full"></div>
                       <div className="absolute inset-0 border-4 border-emerald-500 rounded-full border-t-transparent animate-spin"></div>
                    </div>
                    <p className="text-slate-400 animate-pulse">Consultando legislação vigente...</p>
                  </div>
                ) : activeAnalysis.result ? (
                  <div className="prose prose-invert prose-emerald max-w-none">
                     {formatMarkdown(activeAnalysis.result.markdown)}
                     <div className="mt-8 pt-4 border-t border-slate-800 text-xs text-slate-500 flex justify-between">
                        <span>Análise gerada em: {activeAnalysis.result.timestamp}</span>
                        <span>Fonte: Base de conhecimento IA</span>
                     </div>
                  </div>
                ) : null}
              </div>
            </div>
          </div>
        )}

      </main>

      {/* Footer / Legal Warning */}
      <footer className="w-full border-t border-slate-800 bg-[#020617] pt-12 pb-8">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">

           <div className="bg-orange-900/20 border border-orange-900/50 rounded-xl p-6 mb-12 flex gap-4 items-start">
              <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-6 h-6 text-orange-500 flex-shrink-0 mt-0.5">
                <path strokeLinecap="round" strokeLinejoin="round" d="M12 9v3.75m-9.303 3.376c-.866 1.5.217 3.374 1.948 3.374h14.71c1.73 0 2.813-1.874 1.948-3.374L13.949 3.378c-.866-1.5-3.032-1.5-3.898 0L2.697 16.126zM12 15.75h.007v.008H12v-.008z" />
              </svg>
              <div>
                <h4 className="text-orange-400 font-bold text-sm mb-1 uppercase tracking-wide">Aviso Legal</h4>
                <p className="text-slate-400 text-sm leading-relaxed">
                  As informações disponibilizadas nesta plataforma são de caráter consultivo e geradas por Inteligência Artificial. Elas não substituem o aconselhamento profissional. Recomendamos fortemente que todas as decisões tributárias sejam validadas por contadores ou advogados tributaristas devidamente habilitados antes de qualquer implementação.
                </p>
              </div>
           </div>

           <div className="grid grid-cols-1 md:grid-cols-4 gap-8 mb-8 text-sm">
              <div className="col-span-1 md:col-span-2">
                 <h5 className="text-white font-bold mb-4">Tax<span className="text-emerald-500">Region</span> BR</h5>
                 <p className="text-slate-500 max-w-xs">Inteligência tributária estadual para auxiliar empresas na navegação dos incentivos fiscais regionais do Brasil.</p>
              </div>
              <div>
