import { GoogleGenAI } from "@google/genai";
import { State, TaxTopic } from '../types';

// Use gemini-3-pro-preview for complex reasoning tasks like tax analysis
const MODEL_NAME = 'gemini-3-pro-preview';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeTaxScenario = async (state: State, topic: TaxTopic): Promise<string> => {
  const prompt = `
    Você é um consultor tributário sênior especializado em legislação brasileira (Tax Intelligence).

    Tarefa: Forneça uma análise estratégica sobre "${topic.title}" especificamente para o estado de ${state.name} (${state.uf}).

    Estruture a resposta em Markdown claro e profissional com os seguintes pontos:
    1. **Resumo Executivo**: Uma visão geral da postura do estado quanto a ${topic.title}.
    2. **Principais Oportunidades**: Liste benefícios, incentivos ou regimes vigentes mais relevantes.
    3. **Legislação Chave**: Cite as leis ou decretos estaduais relevantes (se houver conhecimento específico, caso contrário, indique como buscar).
    4. **Pontos de Atenção**: Riscos ou exigências comuns para adesão.

    Contexto adicional: O usuário busca otimização fiscal. Seja objetivo, mas detalhado o suficiente para gerar valor. Use formatação em tópicos.

    Importante: Adicione um aviso ao final de que a legislação muda frequentemente e a consulta oficial é indispensável.
  `;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: {
        thinkingConfig: { thinkingBudget: 1024 }, // Enable thinking for deeper analysis
      }
    });
    return response.text || "Não foi possível gerar a análise no momento.";
  } catch (error) {
    console.error("Error fetching tax analysis:", error);
    return "Ocorreu um erro ao consultar a inteligência tributária. Por favor, tente novamente.";
  }
};

export const analyzeCNPJOpportunities = async (cnpj: string): Promise<string> => {
  const prompt = `
    Você é um consultor tributário sênior (Tax Intelligence) do TaxRegion BR.

    Tarefa: Analisar oportunidades tributárias para a empresa portadora do CNPJ: ${cnpj}.

    Como assistente de IA, você não tem acesso ao banco de dados privado da Receita em tempo real, mas deve realizar a análise baseada na identificação provável do setor ou simulação.

    Por favor:
    1. **Análise de Perfil (CNAE)**: Tente identificar a atividade econômica (setor) provável com base no conhecimento prévio sobre grandes empresas (se o CNPJ for conhecido) ou assuma um perfil típico (ex: Indústria, Comércio Varejista, Tecnologia) se não puder identificar, explicando que a análise é baseada nesse perfil estimado.
    2. **Diagnóstico de Oportunidades**: Liste as principais teses tributárias e oportunidades vigentes no Brasil para este perfil de empresa. Inclua:
       - Recuperação de Créditos (PIS/COFINS, etc).
       - Incentivos Fiscais (Federais e sugestões de Estaduais comuns).
       - Regimes Especiais aplicáveis ao setor.
    3. **Plano de Ação**: 3 passos práticos para o empresário verificar a viabilidade.

    Estruture a resposta em Markdown profissional, com títulos claros e listas.
    IMPORTANTE: Adicione um aviso legal de que esta análise é uma simulação baseada em IA e requer validação técnica contábil.
  `;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: {
        thinkingConfig: { thinkingBudget: 2048 },
      }
    });
    return response.text || "Não foi possível realizar a análise do CNPJ no momento.";
  } catch (error) {
    console.error("Error analyzing CNPJ:", error);
    return "Ocorreu um erro ao processar o CNPJ. Verifique se o número está correto e tente novamente.";
  }
};

export const chatWithTaxExpert = async (message: string, history: {role: string, parts: {text: string}[]}[]): Promise<string> => {
  try {
    const chat = ai.chats.create({
      model: MODEL_NAME,
      history: [
        {
          role: 'user',
          parts: [{ text: "Você é o assistente virtual do TaxRegion BR. Você ajuda com dúvidas sobre tributação estadual no Brasil. Seja profissional, conciso e sempre lembre que suas respostas são consultivas e não substituem parecer jurídico. Responda sempre em Português." }]
        },
        {
          role: 'model',
          parts: [{ text: "Entendido. Sou o assistente do TaxRegion BR e estou pronto para auxiliar com inteligência tributária, mantendo o tom profissional e consultivo." }]
        },
        ...history
      ],
    });

    const response = await chat.sendMessage({ message });
    return response.text || "Desculpe, não consegui processar sua pergunta.";
  } catch (error) {
    console.error("Chat error:", error);
    return "Erro de conexão com o assistente inteligente.";
  }
};

import React, { useState } from 'react';
import { BRAZIL_STATES, TAX_TOPICS } from './constants';
import { State, TaxTopic, AnalysisResult, TaxTopicId } from './types';
import { analyzeTaxScenario, analyzeCNPJOpportunities } from './services/geminiService';
import { IconChart, IconDocument, IconLocation, IconGemini, IconArrowRight, IconBuilding } from './components/Icons';
import ChatBot from './components/ChatBot';

const App: React.FC = () => {
  const [searchMode, setSearchMode] = useState<'state' | 'cnpj'>('state');
  const [selectedState, setSelectedState] = useState<State | null>(null);
  const [cnpj, setCnpj] = useState('');
  const [activeAnalysis, setActiveAnalysis] = useState<{ topic: TaxTopic; result: AnalysisResult | null; loading: boolean } | null>(null);

  const handleStateChange = (event: React.ChangeEvent<HTMLSelectElement>) => {
    const uf = event.target.value;
    const state = BRAZIL_STATES.find((s) => s.uf === uf) || null;
    setSelectedState(state);
    // Reset analysis if state changes
    setActiveAnalysis(null);
  };

  const handleCnpjChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    let value = event.target.value.replace(/\D/g, '');
    if (value.length > 14) value = value.slice(0, 14);

    // Mask logic
    value = value.replace(/^(\d{2})(\d)/, '$1.$2');
    value = value.replace(/^(\d{2})\.(\d{3})(\d)/, '$1.$2.$3');
    value = value.replace(/\.(\d{3})(\d)/, '.$1/$2');
    value = value.replace(/(\d{4})(\d)/, '$1-$2');

    setCnpj(value);
  };

  const handleCnpjSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (cnpj.length < 18) return; // Basic validation for full masked length

    const cnpjTopic: TaxTopic = {
      id: 'cnpj_analysis' as any, // Cast to any to bypass generic constraint for this special case
      title: 'Análise de Oportunidades (CNPJ)',
      description: 'Análise completa baseada no perfil do CNPJ',
      icon: 'document'
    };

    setActiveAnalysis({ topic: cnpjTopic, result: null, loading: true });

    const startTime = Date.now();
    const markdown = await analyzeCNPJOpportunities(cnpj);
    const endTime = Date.now();

    const elapsed = endTime - startTime;
    if (elapsed < 1500) { // Slightly longer minimal wait for "processing" feel
      await new Promise(resolve => setTimeout(resolve, 1500 - elapsed));
    }

    setActiveAnalysis({
      topic: cnpjTopic,
      result: {
        markdown,
        timestamp: new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })
      },
      loading: false
    });
  };

  const handleTopicClick = async (topic: TaxTopic) => {
    if (!selectedState) {
      // Focus on selector if no state selected
      const selector = document.getElementById('state-selector');
      if (selector) {
        selector.focus();
        selector.classList.add('ring-2', 'ring-emerald-500', 'ring-offset-2', 'ring-offset-slate-900');
        setTimeout(() => selector.classList.remove('ring-2', 'ring-emerald-500', 'ring-offset-2', 'ring-offset-slate-900'), 1000);
      }
      return;
    }

    setActiveAnalysis({ topic, result: null, loading: true });

    // Simulate loading feel or actual delay for UI smoothing if API is too fast/slow
    const startTime = Date.now();
    const markdown = await analyzeTaxScenario(selectedState, topic);
    const endTime = Date.now();

    // Ensure at least 800ms loading for UX presence
    const elapsed = endTime - startTime;
    if (elapsed < 800) {
      await new Promise(resolve => setTimeout(resolve, 800 - elapsed));
    }

    setActiveAnalysis({
      topic,
      result: {
        markdown,
        timestamp: new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })
      },
      loading: false
    });
