                </h1>
                <p className="text-[10px] text-slate-400 uppercase tracking-widest leading-none mt-0.5">Inteligência Tributária</p>
             </div>
          </div>

          <div className="hidden md:flex items-center gap-2 px-3 py-1.5 rounded-full bg-slate-900 border border-slate-800">
            <IconGemini className="w-4 h-4 text-emerald-500" />
            <span className="text-xs font-medium text-slate-300">Powered by Gemini</span>
          </div>
        </div>
