import { jsPDF } from "jspdf";
import { AnalysisResult, State } from '../types';

interface ExportData {
  result: AnalysisResult;
  topicTitle: string;
  context: string; // State Name or CNPJ
}

export const exportToCSV = (data: ExportData) => {
  const { result, topicTitle, context } = data;

  // Clean markdown for simple text representation
  const cleanText = result.markdown
    .replace(/#/g, '')
    .replace(/\*\*/g, '')
    .replace(/\*/g, '')
    .replace(/"/g, '""'); // Escape quotes for CSV

  const rows = [
    ["Relatório", "TaxRegion BR - Inteligência Tributária"],
    ["Data de Geração", result.timestamp],
    ["Contexto", context],
    ["Tópico", topicTitle],
    [],
    ["Conteúdo da Análise"],
    [cleanText]
  ];

  const csvContent = "\uFEFF" + rows.map(e => e.map(c => `"${c}"`).join(";")).join("\n");

  const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");

  const filename = `TaxRegion_Relatorio_${context.replace(/[^a-zA-Z0-9]/g, '')}_${Date.now()}.csv`;

  link.setAttribute("href", url);
  link.setAttribute("download", filename);
  link.style.visibility = 'hidden';
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
};

export const exportToPDF = (data: ExportData) => {
  const { result, topicTitle, context } = data;
  const doc = new jsPDF();

  // Configs
  const marginLeft = 20;
  const marginTop = 20;
  const lineHeight = 7;
  const pageWidth = doc.internal.pageSize.getWidth();
  const maxLineWidth = pageWidth - (marginLeft * 2);
  let y = marginTop;

  // Header
  doc.setFontSize(18);
  doc.setTextColor(0, 150, 100); // Emerald color alike
  doc.text("TaxRegion BR", marginLeft, y);
  y += 10;

  doc.setFontSize(12);
  doc.setTextColor(100, 100, 100);
  doc.text("Relatório de Inteligência Tributária", marginLeft, y);
  y += 15;

  // Metadata
  doc.setFontSize(10);
  doc.setTextColor(0, 0, 0);
  doc.text(`Contexto: ${context}`, marginLeft, y);
  y += 6;
  doc.text(`Tópico: ${topicTitle}`, marginLeft, y);
  y += 6;
  doc.text(`Data: ${result.timestamp}`, marginLeft, y);
  y += 15;

  // Content processing
  // Remove complex markdown structure but keep basic readability
  const lines = result.markdown.split('\n');

  doc.setFontSize(11);

  lines.forEach((line) => {
    // Check page break
    if (y > 280) {
      doc.addPage();
      y = marginTop;
    }

    let text = line.trim();

    // Formatting headings
    if (text.startsWith('###') || text.startsWith('##') || text.startsWith('#')) {
      doc.setFont("helvetica", "bold");
      text = text.replace(/#/g, '').trim();
      y += 5; // Extra space before headers
    } else if (text.startsWith('**') && text.endsWith('**')) {
       // Bold lines
       doc.setFont("helvetica", "bold");
       text = text.replace(/\*\*/g, '').trim();
    } else {
      doc.setFont("helvetica", "normal");
      text = text.replace(/\*\*/g, ''); // Remove bold markers inline
    }

    if (text.length > 0) {
      const splitText = doc.splitTextToSize(text, maxLineWidth);
      doc.text(splitText, marginLeft, y);
      y += (splitText.length * lineHeight); 
    } else {
        y += lineHeight / 2; // Smaller gap for empty lines
    }
  });

  // Footer Disclaimer
  if (y > 270) {
      doc.addPage();
      y = marginTop;
  }
  y += 10;
  doc.setFontSize(8);
  doc.setTextColor(150, 150, 150);
  const footer = "Aviso: Este relatório foi gerado por IA. As informações são consultivas e devem ser validadas por um profissional.";
  const splitFooter = doc.splitTextToSize(footer, maxLineWidth);
  doc.text(splitFooter, marginLeft, y);

  const filename = `TaxRegion_Relatorio_${context.replace(/[^a-zA-Z0-9]/g, '')}_${Date.now()}.pdf`;
  doc.save(filename);
};

